import sys
from typing import List

def max_operations(N: int, a: List[int]) -> int:
    operations = 0
    while True:
        all_even = True
        new_a = []
        for num in a:
            if num % 2 != 0:
                all_even = False
                break
            else:
                new_a.append(num // 2)
        if all_even:
            a = new_a
            operations += len(a)
        else:
            break
    return operations

