def max_operations(N, a):
    operations = 0
    while True:
        if all(x % 2 == 0 for x in a) and all(x % 3 != 0 for x in a):
            break
        for i in range(N):
            if a[i] % 2 == 0:
                a[i] //= 2
            elif a[i] % 3 == 0:
                a[i] *= 3
        operations += 1
    return operations

